249	// ---------- 课程 ----------
250	
251	// Action 描述登记类操作相对已有记录做了什么。
252	type Action string
253	
254	const (
255		// ActionCreated 新建了记录。
256		ActionCreated Action = "created"
257		// ActionExisted 记录已存在且内容一致，原样返回（幂等）。
258		ActionExisted Action = "existed"
259		// ActionUpdated 记录已存在，本次在允许范围内更新了内容。
260		ActionUpdated Action = "updated"
261	)
262	
263	// AddCourse 登记课程，学分为正整数，新课程初始开放。
264	// 编号已存在且名称、学分完全相同时原样返回（幂等），停开/开放状态不变。
265	// 编号相同但学分不同：该课程尚未被任何课程要求引用时允许修改并保持开放
266	// 状态；已经被要求引用的课程不能修改学分，请求被拒绝且课程保持不变。
267	//
268	// 课程编号按用户给出的完整文字参与匹配与保存，前后空白（普通空格、制表符、
269	// 全角空格等）也是编号内容，绝不修剪：记录文件可以合法保存 “c1” 与 “ c1 ”
270	// 两门独立课程，登记与重复判断必须命中编号完全一致的那一门，并保留编号原文。
271	// 完整编号找不到时一律新建，绝不借用去掉空白后能碰上的另一门课程的名称、
272	// 学分或停开/开放状态；再次提交某个完整编号时只判断对应课程：名称与学分
273	// 相同则返回原记录，内容不同仍按上述规则更新对应课程，不新增副本、不改动
274	// 另一门课程。学分锁定跟随实际命中的课程：只有要求引用了该完整编号的课程
275	// 时才禁止修改它的学分，另一门同号不同空白课程是否被引用与此无关。
276	// 编号为空字符串，或全部由空白字符组成（普通空格、制表符、全角空格等，
277	// 允许混用）时直接拒绝；含实际文字的编号原样保存。课程名称沿用现有输入
278	// 规则：前后空白不计入名称内容，修剪后为空则拒绝。
279	func (s *Store) AddCourse(id, name string, credit int) (c *Course, action Action, err error) {
280		name = strings.TrimSpace(name)
281		if id == "" {
282			return nil, "", errors.New("课程编号不能为空")
283		}
284		if strings.TrimSpace(id) == "" {
285			return nil, "", errors.New("课程编号不能只由空白字符组成")
286		}
287		if name == "" {
288			return nil, "", errors.New("课程名称不能为空")
289		}
290		if credit <= 0 {
291			return nil, "", fmt.Errorf("课程学分必须是正整数，得到 %d", credit)
292		}
293		if existing := s.courseByID[id]; existing != nil {
294			if existing.Name == name && existing.Credit == credit {
295				return existing, ActionExisted, nil
296			}
297			if existing.Credit != credit && s.courseReferenced(id) {
298				return nil, "", fmt.Errorf(
299					"课程 %s 已被课程要求引用，不能修改学分（原学分 %d），原记录保留",
300					id, existing.Credit)
301			}
302			existing.Name = name
303			existing.Credit = credit
304			s.dirty = true
305			return existing, ActionUpdated, nil
306		}
307		c = &Course{ID: id, Name: name, Credit: credit, Open: true}
308		s.courses = append(s.courses, c)
309		s.courseByID[id] = c
310		s.dirty = true
311		return c, ActionCreated, nil
312	}
313	
314	// courseReferenced 报告课程是否被任何学生的课程要求引用。
315	func (s *Store) courseReferenced(id string) bool {
316		for _, r := range s.requirements {
317			if r.CourseID == id {
318				return true
319			}
320		}
321		return false
322	}
