324	// SetCourseOpen 设置课程开放状态。课程不存在时报错；状态相同则原样返回。
325	func (s *Store) SetCourseOpen(id string, open bool) (*Course, error) {
326		c := s.courseByID[id]
327		if c == nil {
328			return nil, fmt.Errorf("课程 %s 不存在", id)
329		}
330		if c.Open != open {
331			c.Open = open
332			s.dirty = true
333		}
334		return c, nil
335	}
