337	// ---------- 课程要求 ----------
338	
339	// AddRequirement 为学生登记一项指向课程的要求。
340	// 同一要求编号已存在且指向同一课程时返回原要求（幂等）；指向不同课程则拒绝。
341	// 同一学生就同一课程已有要求（即使编号不同）也拒绝。学生或课程不存在时拒绝。
342	//
343	// 学生编号、要求编号与课程编号按用户给出的完整文字参与匹配，前后空白
344	// （普通空格、制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以
345	// 合法保存 “s1” 与 “ s1 ” 两名学生、“c1” 与 “ c1 ” 两门课程、同一学生
346	// 名下 “r1” 与 “ r1 ” 两项要求，登记必须命中编号完全一致的学生与课程，
347	// 新要求也必须登记在完整编号的学生名下并保留完整编号。完整编号找不到
348	// 学生时报告学生不存在，完整编号找不到课程时报告课程不存在——即使去掉
349	// 空白能碰上另一名学生或另一门课程，也绝不借用那份记录，更不能自动创建
350	// 学生或课程。编号为空字符串时直接拒绝；要求编号只由空白字符组成时
351	// 不得建立。这与选课、免修、查询使用的对象完全一致：已有带空白编号的
352	// 合法记录继续按原样读取，不因登记而被改写、合并或重新解释。
353	// 课程是否停开不影响建立要求：新要求本身不带来学分，之后只有通过修读
354	// 或有效免修才能满足它。
355	func (s *Store) AddRequirement(studentID, reqID, courseID string) (r *Requirement, action Action, err error) {
356		if studentID == "" || reqID == "" || courseID == "" {
357			return nil, "", errors.New("学生编号、要求编号和课程编号不能为空")
358		}
359		if strings.TrimSpace(reqID) == "" {
360			return nil, "", errors.New("要求编号不能只由空白字符组成")
361		}
362		if _, ok := s.studentByID[studentID]; !ok {
363			return nil, "", fmt.Errorf("学生 %s 不存在，不能登记课程要求", studentID)
364		}
365		c := s.courseByID[courseID]
366		if c == nil {
367			return nil, "", fmt.Errorf("课程 %s 不存在，不能登记课程要求", courseID)
368		}
369		if existing := s.reqByKey[reqKey(studentID, reqID)]; existing != nil {
370			if existing.CourseID != courseID {
371				return nil, "", fmt.Errorf(
372					"学生 %s 的要求编号 %s 已指向课程 %s，不能改指课程 %s",
373					studentID, reqID, existing.CourseID, courseID)
374			}
375			return existing, ActionExisted, nil
376		}
377		if otherID, ok := s.reqByDup[dupKey(studentID, courseID)]; ok {
378			return nil, "", fmt.Errorf(
379				"学生 %s 已就课程 %s 建立要求 %s，不能重复建立", studentID, courseID, otherID)
380		}
381		r = &Requirement{ID: reqID, StudentID: studentID, CourseID: courseID}
382		s.requirements = append(s.requirements, r)
383		s.reqByKey[reqKey(studentID, reqID)] = r
384		s.reqByDup[dupKey(studentID, courseID)] = reqID
385		s.dirty = true
386		return r, ActionCreated, nil
387	}
