389	// ---------- 修读 ----------
390	
391	// AddEnrollment 为学生的一项要求登记某学期的修读，初始状态为“选课”。
392	// 相同（学生、修读编号、要求、学期）的重复登记返回原记录（幂等）；
393	// 相同编号但要求或学期不同则拒绝；课程已停开时不能新增修读
394	// （已登记记录的重复提交仍按幂等返回原记录）。
395	//
396	// 学生编号、要求编号与修读编号按用户给出的完整文字参与匹配，前后空白
397	// （普通空格、制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以
398	// 合法保存 “s1” 与 “ s1 ” 两名学生、同一学生名下 “r1” 与 “ r1 ” 两项
399	// 要求、“e1” 与 “ e1 ” 两份修读，登记必须命中编号完全一致的对象，新
400	// 修读也必须登记在完整编号的学生与要求名下并保留完整编号。完整编号找
401	// 不到学生时报告学生不存在；学生存在但名下没有该完整要求编号时报告本人
402	// 名下没有该要求——即使去掉空白能碰上另一名学生或另一项要求，也绝不
403	// 借用那份记录，更不能把修读登记到别人名下。编号为空字符串时直接拒绝；
404	// 只由空白字符组成的修读编号不得建立。学期沿用现有输入规则：前后空白
405	// 不计入学期内容，修剪后为空则拒绝。
406	func (s *Store) AddEnrollment(studentID, reqID, term, enrID string) (e *Enrollment, action Action, err error) {
407		term = strings.TrimSpace(term)
408		if studentID == "" || reqID == "" || enrID == "" {
409			return nil, "", errors.New("学生编号、要求编号和修读编号不能为空")
410		}
411		if strings.TrimSpace(enrID) == "" {
412			return nil, "", errors.New("修读编号不能只由空白字符组成")
413		}
414		if term == "" {
415			return nil, "", errors.New("学期不能为空")
416		}
417		if _, ok := s.studentByID[studentID]; !ok {
418			return nil, "", fmt.Errorf("学生 %s 不存在，不能登记修读", studentID)
419		}
420		r := s.reqByKey[reqKey(studentID, reqID)]
421		if r == nil {
422			return nil, "", fmt.Errorf("学生 %s 名下不存在要求 %s，不能登记修读", studentID, reqID)
423		}
424		if existing := s.enrByKey[reqKey(studentID, enrID)]; existing != nil {
425			if existing.ReqID != reqID || existing.Term != term {
426				return nil, "", fmt.Errorf(
427					"学生 %s 的修读编号 %s 已用于要求 %s、学期 %s，不能改为要求 %s、学期 %s",
428					studentID, enrID, existing.ReqID, existing.Term, reqID, term)
429			}
430			return existing, ActionExisted, nil
431		}
432		c := s.courseByID[r.CourseID]
433		if c == nil || !c.Open {
434			return nil, "", fmt.Errorf("课程 %s 已停开，不能新增修读", r.CourseID)
435		}
436		e = &Enrollment{
437			ID: enrID, StudentID: studentID, ReqID: reqID, Term: term, Result: Enrolled,
438		}
439		s.enrollments = append(s.enrollments, e)
440		s.enrByKey[reqKey(studentID, enrID)] = e
441		s.dirty = true
442		return e, ActionCreated, nil
443	}
444	
445	// SubmitResult 为修读提交通过/未通过结果。
446	// 重复提交相同结果返回原记录（幂等，不累加学分）；已提交结果后改提另一结果
447	// 一律拒绝并保留原记录。
448	//
449	// 首次提交结果会从全局递增计数器领取一个结果提交序号（ResultSeq），用于
450	// 记录多次提交的先后关系；通过与未通过都占用一次序号。计数器是整数类型
451	// int：当它已经达到该类型可表示的最大值（64 位环境下为
452	// 9223372036854775807）时，再递增必然回绕成负数并保存，会破坏整份记录
453	// （负序号、与原有序号的先后关系错乱、记录无法再正常读取）。因此计数已
454	// 到上限时，任何仍处于“选课”的修读都不能再首次提交结果：明确拒绝，不
455	// 改结果、不发序号、不标记变更；不会因该要求已有另一份通过修读或已有
456	// 有效免修而放行，也不能从小重新编号、借用历史空缺编号或改排已有成绩。
457	// 距上限恰好还差一时允许最后一次正常的首次提交，其先后关系照常保留；
458	// 未通过同样占用这最后一次机会且仍不计学分。已经提交过结果的修读不
459	// 需要新序号：重复提交相同结果仍幂等返回原记录，改提另一结果仍按冲突
460	// 规则拒绝。
461	//
462	// 学生编号与修读编号按用户给出的完整文字参与匹配，前后空白（普通空格、
463	// 制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以合法保存
464	// “s1”与“ s1 ”两名学生、同一学生名下“e1”与“ e1 ”两份修读，提交
465	// 必须命中编号完全一致的那一份。完整编号找不到学生时报告学生不存在；
466	// 学生存在但名下没有该完整修读编号时报告该修读不存在——即使去掉空白后
467	// 能碰上另一名学生或另一份修读，也绝不借用那份记录，更不能据此补建修读。
468	func (s *Store) SubmitResult(studentID, enrID string, result Result) (e *Enrollment, changed bool, err error) {
469		if result != Passed && result != Failed {
470			return nil, false, fmt.Errorf("修读结果只能是 %s 或 %s", Passed, Failed)
471		}
472		if _, ok := s.studentByID[studentID]; !ok {
473			return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
474		}
475		e = s.enrByKey[reqKey(studentID, enrID)]
476		if e == nil {
477			return nil, false, fmt.Errorf("学生 %s 名下不存在修读 %s", studentID, enrID)
478		}
479		if e.Result == result {
480			return e, false, nil
481		}
482		if e.Result != Enrolled {
483			return nil, false, fmt.Errorf(
484				"修读 %s 已提交结果“%s”，不能改为“%s”，原结果保留", enrID, zhResult(e.Result), zhResult(result))
485		}
486		// 首次提交必须领取新的结果序号。计数器已达 int 上限时不能再递增：
487		// MaxInt+1 会静默回绕成 MinInt 并随修读落盘，随后连原有记录都无法
488		// 正常读取。这里在改动任何状态之前拒绝，保持修读为选课、整份记录
489		// 原样不变。是否还能提交只取决于计数器本身：不重新从小编号、不
490		// 借用历史空缺编号，也不因该要求另有通过修读或有效免修而放行。
491		if s.nextResultSeq >= math.MaxInt {
492			return nil, false, fmt.Errorf(
493				"学生 %s 的修读 %s 不能提交成绩：成绩提交顺序编号已用尽（已达本程序整数类型最大值 %d），无法提交新的成绩，原记录保留",
494				studentID, enrID, math.MaxInt)
495		}
496		s.nextResultSeq++
497		e.Result = result
498		e.ResultSeq = s.nextResultSeq
499		s.dirty = true
500		return e, true, nil
501	}
502	
503	// ---------- 免修 ----------
504	
505	// ApplyWaiver 提交免修申请，依据必须含实际文字。
506	//
507	// 首次提交且内容合法：状态为有效（approved），action=created。
508	// 目标要求不存在（含要求属于其他学生）、依据不含实际文字、或该要求已有
509	// 有效免修：申请被拒绝，但申请内容与具体原因保留在该学生的免修历史中，
510	// 返回的申请状态为 rejected（仍属于新建记录，action=created）。
511	// 同一编号已存在：内容（要求、依据）完全相同时返回原申请及其结果
512	// （已拒绝/已撤销的申请不会因重试重新生效）；内容不同则拒绝且不改动原申请。
513	//
514	// 学生编号、要求编号与免修编号按用户给出的完整文字参与匹配，前后空白
515	// （普通空格、制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以
516	// 合法保存 “s1” 与 “ s1 ” 两名学生、同一学生名下 “r1” 与 “ r1 ” 两项
517	// 要求、“w1” 与 “ w1 ” 两份申请，提交必须命中编号完全一致的那一项，
518	// 申请也必须登记在完整编号的申请人名下。完整编号找不到学生时直接按业务
519	// 规则报错，不在任何学生名下新增历史；学生存在但名下没有该完整要求编号
520	// 时，即使去掉空白能碰上另一项要求，也绝不借用那份记录，而是按原规则在
521	// 申请人名下保存原要求编号、免修编号、依据原文与拒绝原因。编号为空字符串
522	// 时直接拒绝，不创建申请。依据含实际文字时其中的空白（包括前后空白）
523	// 原样保留；是否“没有依据”只按空白内容判定（见 blankBasis），绝不修剪
524	// 或改写依据原文。
525	func (s *Store) ApplyWaiver(studentID, reqID, waiverID, basis string) (w *Waiver, action Action, err error) {
526		if studentID == "" || reqID == "" || waiverID == "" {
527			return nil, "", errors.New("学生编号、要求编号和免修编号不能为空")
528		}
529		if _, ok := s.studentByID[studentID]; !ok {
530			return nil, "", fmt.Errorf("学生 %s 不存在，不能申请免修", studentID)
531		}
532		if existing := s.waiverByKey[reqKey(studentID, waiverID)]; existing != nil {
533			if existing.ReqID != reqID || existing.Basis != basis {
534				return nil, "", fmt.Errorf(
535					"学生 %s 的免修编号 %s 已存在（要求 %s、依据 %q），提交内容不同，拒绝修改",
536					studentID, waiverID, existing.ReqID, existing.Basis)
537			}
538			return existing, ActionExisted, nil
539		}
540	
541		w = &Waiver{ID: waiverID, StudentID: studentID, ReqID: reqID, Basis: basis}
542		switch {
543		case s.reqByKey[reqKey(studentID, reqID)] == nil:
544			w.Status = WaiverRejected
545			w.Reason = fmt.Sprintf("目标要求 %s 不存在或不属于该学生", reqID)
546		case blankBasis(basis):
547			w.Status = WaiverRejected
548			w.Reason = "免修依据为空"
549		default:
550			if other := s.validWaiver(studentID, reqID); other != nil {
551				w.Status = WaiverRejected
552				w.Reason = fmt.Sprintf("该要求已有有效免修 %s", other.ID)
553				break
554			}
555			w.Status = WaiverApproved
556		}
557		s.waivers = append(s.waivers, w)
558		s.waiverByKey[reqKey(studentID, waiverID)] = w
559		s.dirty = true
560		return w, ActionCreated, nil
561	}
562	
563	// validWaiver 返回某要求当前有效的免修。
564	func (s *Store) validWaiver(studentID, reqID string) *Waiver {
565		for _, w := range s.waivers {
566			if w.StudentID == studentID && w.ReqID == reqID && w.Status == WaiverApproved {
567				return w
568			}
569		}
570		return nil
571	}
572	
573	// RevokeWaiver 撤销有效免修，原依据与撤销状态保留；reason 可填撤销原因。
574	// 重复撤销已撤销的免修：原样返回、changed=false，不改变结果。
575	// 撤销不存在的编号或撤销已被拒绝的申请：明确拒绝。
576	//
577	// 学生编号与免修编号按用户给出的完整文字参与匹配，前后空白（普通空格、
578	// 制表符、全角空格等）也是编号内容，绝不修剪：记录文件可以合法保存
579	// “s1”与“ s1 ”两名学生、同一学生名下“w1”与“ w1 ”两份免修，撤销
580	// 必须命中编号完全一致的那一份。完整编号找不到学生时报告学生不存在；
581	// 学生存在但名下没有该完整免修编号时报告该免修不存在——即使去掉空白后
582	// 能碰上另一名学生或另一份免修，也绝不借用那份记录，更不能改写原编号、
583	// 合并申请或新增免修历史。撤销提示与免修历史一律使用实际命中的原编号。
584	func (s *Store) RevokeWaiver(studentID, waiverID, reason string) (w *Waiver, changed bool, err error) {
585		reason = strings.TrimSpace(reason)
586		if _, ok := s.studentByID[studentID]; !ok {
587			return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
588		}
589		w = s.waiverByKey[reqKey(studentID, waiverID)]
590		if w == nil {
591			return nil, false, fmt.Errorf("学生 %s 名下不存在免修 %s，不能撤销", studentID, waiverID)
592		}
593		switch w.Status {
594		case WaiverApproved:
595			w.Status = WaiverRevoked
596			if reason == "" {
597				reason = "手动撤销"
598			}
599			w.Reason = reason
600			s.dirty = true
601			return w, true, nil
602		case WaiverRevoked:
603			return w, false, nil
604		default:
605			return nil, false, fmt.Errorf("免修 %s 已被拒绝，不能撤销（拒绝原因：%s）", waiverID, w.Reason)
606		}
607	}
608

