// 已有记录、退出码 0、文件逐字节不变；历史不移动、不合并。
func TestCLIStudentWhitespaceIdempotentHitsExactOwner(t *testing.T) {
	d := &diskRecord{
		Version: 1,
		Courses: []diskCourse{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
		Students: []diskStudent{
			{ID: "s1"},
