		!strings.Contains(out, "修读 e1") {
		t.Fatalf("\"s1\" 的原有记录应保持不变，code=%d out=%q", code, out)
	}
	out, _, code = runCLI(t, file, "check", "s1")
	if code != 0 || !strings.Contains(out, "总学分：4") ||
		!strings.Contains(out, "来源为通过修读 e1") {
