	// 文件中只有 " s1 "：用 "s1" 查询应明确报不存在，不能借到同一记录。
	_, errText, code := runCLI(t, file, "show", "s1")
	if code != exitRejected || !strings.Contains(errText, "学生 s1 不存在") {
		t.Fatalf("\"s1\" 应查不到 \" s1 \"，code=%d err=%q", code, errText)
	}
}

